  ('Her x gerçek sayısı için aşağıdaki eşitliklerden hangisi her zaman doğrudur?', '|x|² = x²', ['|x| = x', '|−x| = −x', '|x + 1| = |x| + 1'], 'Bir sayının mutlak değerinin karesi sayının karesine eşittir. x = −2 için |x| = x ve |−x| = −x yanlış, x = −3 için |x + 1| = |x| + 1 yanlıştır.'),
  ('2 ≤ |x| ≤ 4 koşulunu sağlayan kaç tam sayı vardır?', '6', ['3', '5', '4'], '|x| değeri 2, 3 ya da 4 olabilir; her biri için iki x (±) vardır: 3 · 2 = 6 tam sayı.'),
  ('Kuvvetleri farklı biçimde yazılmış 8² · 4³ / 2⁷ işleminin sonucu 2\'nin kaçıncı kuvvetidir?', '5', ['6', '7', '12'], '8² = 2⁶, 4³ = 2⁶ olduğundan pay 2¹²\'dir; 2¹² / 2⁷ = 2⁵ bulunur.'),
  ('2¹⁰ + 2¹⁰ toplamı aşağıdakilerden hangisine eşittir?', '2¹¹', ['2²⁰', '4¹⁰', '2¹⁰⁰'], 'Aynı terimden iki tane toplanınca 2 · 2¹⁰ = 2¹¹ olur. Üsleri toplamak yalnız çarpmada geçerlidir.'),
  ('a = 2⁵ ve b = 2⁻³ olduğuna göre a/b oranı 2\'nin kaçıncı kuvvetidir?', '8', ['2', '−15', '−2'], 'Bölmede üsler çıkarılır: 2⁵ / 2⁻³ = 2⁵⁻⁽⁻³⁾ = 2⁸.'),
  ('(1/2)⁻³ + (1/3)⁻² işleminin sonucu hangi doğal sayıdır?', '17', ['5', '1/17', '−17'], '(1/2)⁻³ = 2³ = 8 ve (1/3)⁻² = 3² = 9\'dur; toplam 17 olur.'),
  ('a < 0 olduğuna göre a⁵ · a⁻² · a⁴ ifadesinin işareti için ne söylenebilir?', 'Negatiftir', ['Pozitiftir', 'Sıfırdır', 'a\'nın değerine göre değişir'], 'Üsler toplanır: a⁵⁻²⁺⁴ = a⁷. Negatif bir sayının tek kuvveti negatiftir.'),
  ('Parantezin üsse etkisine dikkat edilerek −3² + (−3)² − (−3)³ hesaplanırsa hangi sonuç bulunur?', '27', ['−27', '45', '9'], '−3² = −9, (−3)² = 9, (−3)³ = −27 olduğundan −9 + 9 + 27 = 27\'dir.'),
  ('x < 0 < y olmak üzere x³ · y² ile x² · y³ ifadelerinin işaretleri sırasıyla hangisidir?', 'Negatif ve pozitif', ['Pozitif ve negatif', 'İkisi de negatif olur', 'İkisi de pozitif'], 'x³ negatif, y² pozitif ⇒ birinci ifade negatif; x² pozitif, y³ pozitif ⇒ ikinci ifade pozitiftir.'),
  ('Negatif ondalık tabanlı ve negatif üslü (−0,5)⁻³ sayısı hangi tam sayıya eşittir?', '−8', ['8', '−1/8', '1/8'], '(−0,5)⁻³ = 1/(−0,5)³ = 1/(−0,125) = −8\'dir.'),
  ('n pozitif tam sayı olmak üzere (−1)²ⁿ⁺¹ − (−1)²ⁿ ifadesinin değeri kaçtır?', '−2', ['0', '2', 'n\'ye göre −2 ya da 2'], '2n + 1 tek, 2n çifttir: (−1)²ⁿ⁺¹ = −1 ve (−1)²ⁿ = 1. Sonuç −1 − 1 = −2.'),
  ('9 ve 27 sayılarını 3\'ün kuvveti olarak yazarak 9ˣ⁻¹ = 27 eşitliğini çözünüz. x kesir olarak neye eşittir?', '5/2', ['2', '3', '−1/2'], 'Her iki taraf 3 tabanında yazılır: 3²⁽ˣ⁻¹⁾ = 3³ ⇒ 2x − 2 = 3 ⇒ x = 5/2.'),
  ('4ˣ = 1/8 eşitliğinde x hangi sayıdır?', '−3/2', ['−2/3', '3/2', '−3'], '2²ˣ = 2⁻³ ⇒ 2x = −3 ⇒ x = −3/2\'dir.'),
  ('5ˣ⁺¹ + 5ˣ = 150 denkleminin çözümü olan x kaçtır?', '2', ['3', '1', '25'], '5ˣ ortak çarpan olarak alınır: 5ˣ(5 + 1) = 150 ⇒ 5ˣ = 25 ⇒ x = 2.'),
  ('3 üzeri x\'in 7\'ye eşit olduğu biliniyor. Bu bilgiyi kullanarak 9ˣ⁺¹ sayısını hesaplayınız.', '441', ['63', '147', '1323'], '9ˣ⁺¹ = 9 · 9ˣ = 9 · (3ˣ)² = 9 · 49 = 441\'dir.'),
  ('x⁴ = 81 denklemini sağlayan gerçek sayıların toplamı kaçtır?', '0', ['3', '6', '−3'], 'Gerçek çözümler x = 3 ve x = −3\'tür; toplamları 0\'dır. Çift kuvvetli denklemlerde negatif kök de unutulmamalıdır.'),
  ('2¹⁰ · 5⁸ çarpımı kaç basamaklı bir doğal sayıdır?', '9', ['10', '11', '18'], '2¹⁰ · 5⁸ = 2² · (2 · 5)⁸ = 4 · 10⁸\'dir; 4\'ün ardına 8 sıfır gelir ve sayı 9 basamaklıdır.'),
  ('Kuvvetleri karşılaştırma bilgisine göre aşağıdakilerden hangisi en büyüktür?', '3⁴⁰', ['9¹⁹', '27¹³', '81⁹'], 'Hepsi 3 tabanında yazılırsa 3⁴⁰, 3³⁸, 3³⁹ ve 3³⁶ olur; en büyük üs 40\'tır.'),
  ('4¹⁵ · 5²⁸ çarpımının sonunda (sağında) kaç tane sıfır vardır?', '28', ['58', '30', '43'], '4¹⁵ = 2³⁰\'dur. 2³⁰ · 5²⁸ = 2² · 10²⁸ = 4 · 10²⁸ olduğundan sayının sonunda 28 sıfır bulunur.'),
  ('5¹² · 8⁴ çarpımının rakamları toplamı kaçtır?', '1', ['8', '12', '13'], '8⁴ = 2¹² olduğundan çarpım (2 · 5)¹² = 10¹²\'dir; rakamlar toplamı 1\'dir.'),
  ('x harfi 2³⁰ sayısını göstermektedir. 8¹² sayısı x cinsinden nasıl ifade edilir?', 'x · 64', ['x³', 'x · 8', 'x + 6'], '8¹² = 2³⁶ = 2³⁰ · 2⁶ = 64x\'tir.'),
  ('√(0,0049) sayısının değeri nedir?', '0,07', ['0,7', '0,007', '0,49'], '0,0049 = 49/10 000 olduğundan karekökü 7/100 = 0,07\'dir.'),
  ('a = √5 olduğuna göre √20 + √45 + √80 toplamının a cinsinden eşiti hangisidir?', '9a', ['a³', '145a', '3a + 3'], '√20 = 2√5, √45 = 3√5, √80 = 4√5; toplam 9√5 = 9a.'),
  ('Küpkök işlemi yapılırken ∛(−64) + ∛27 ifadesinin değeri nedir?', '−1', ['1', '7', 'Tanımsızdır'], 'Tek dereceli kök negatif sayılarda tanımlıdır: ∛(−64) = −4 ve ∛27 = 3; toplam −1.'),
  ('x < 0 olmak üzere √(x²) ifadesinin eşiti hangisidir?', '−x', ['x', 'x²', '−|x|'], '√(x²) = |x|\'tir. x negatif olduğundan |x| = −x olur.'),
  ('Paydası eşlenikle genişletildiğinde 4/(√7 − √3) kesri hangi biçime dönüşür?', '√7 + √3', ['√7 − √3', '(√7 + √3)/4', '4√7 + 4√3'], 'Pay ve payda √7 + √3 ile çarpılır: 4(√7 + √3)/(7 − 3) = √7 + √3.'),
  ('6/√12 sayısının en sade hâli aşağıdakilerden hangisidir?', '√3', ['2√3', '3/√2', '√6'], '√12 = 2√3 ⇒ 6/(2√3) = 3/√3 = √3.'),
  ('x sayısı 1/(2 − √3) kesrine eşittir. Bu sayı ile çarpmaya göre tersinin toplamı nedir?', '4', ['2√3', '2', '4 + 2√3'], 'x = 2 + √3 ve 1/x = 2 − √3\'tür; toplam 4 olur.'),
  ('√n sayısının 8 ile 9 arasında olmasını sağlayan kaç tane n doğal sayısı vardır?', '16', ['17', '15', '1'], '8 < √n < 9 ⇒ 64 < n < 81; n = 65, 66, ..., 80 olmak üzere 16 değer vardır.'),
  ('√11 sayısına en yakın tam sayı kaçtır?', '3', ['4', '2', '11'], '9 < 11 < 16 olup 11, 9\'a 16\'dan daha yakındır; ayrıca 3,5² = 12,25 > 11 olduğundan √11 < 3,5\'tir. En yakın tam sayı 3\'tür.'),
  ('2 < √x < 3 ve x tam sayı olduğuna göre x\'in en büyük değeri ile en küçük değerinin farkı kaçtır?', '3', ['4', '5', '1'], '4 < x < 9 ⇒ x ∈ {5, 6, 7, 8}; en büyük 8, en küçük 5 olduğundan fark 3\'tür.'),
  ('x + y = 7 ve x · y = 10 olduğuna göre x² + y² toplamı kaçtır?', '29', ['49', '39', '69'], 'x² + y² = (x + y)² − 2xy = 49 − 20 = 29\'dur.'),
  ('İki sayının farkı 3, karelerinin farkı ise 33\'tür. Bu sayılardan büyük olan a hangisidir?', '7', ['11', '10', '8'], 'a² − b² = (a − b)(a + b) ⇒ 33 = 3(a + b) ⇒ a + b = 11. a − b = 3 ile birlikte a = 7 bulunur.'),
  ('x − 1/x = 3 olduğuna göre x² + 1/x² ifadesinin değeri hangisidir?', '11', ['9', '7', '10'], 'Her iki tarafın karesi alınır: x² − 2 + 1/x² = 9 ⇒ x² + 1/x² = 11.'),
  ('İki küp farkı özdeşliğine göre a³ − b³ nasıl yazılır?', '(a − b)(a² + ab + b²)', ['(a − b)³', '(a − b)(a² − ab + b²)', '(a − b)(a² + 2ab + b²)'], 'İki küp farkı özdeşliği: a³ − b³ = (a − b)(a² + ab + b²).'),
  ('x ≠ 3 için (x² − 9)/(x² − 6x + 9) ifadesinin sadeleştirilmiş biçimi hangisidir?', '(x + 3)/(x − 3)', ['x + 3', '(x − 3)/(x + 3)', '(x + 3)/(x − 3)²'], 'Pay (x − 3)(x + 3), payda (x − 3)² olduğundan sadeleşince (x + 3)/(x − 3) kalır.'),
  ('4x² + kx + 9 ifadesi bir tam kare olduğuna göre k\'nin pozitif değeri kaçtır?', '12', ['6', '36', '18'], '(2x + 3)² = 4x² + 12x + 9 olduğundan k = 12\'dir.'),
  ('ab + 2a + 3b + 6 ifadesi gruplandırılarak nasıl çarpanlarına ayrılır?', '(a + 3)(b + 2)', ['(a + 2)(b + 3)', '(a + 6)(b + 1)', '(ab + 6)(2 + 3)'], 'a(b + 2) + 3(b + 2) = (a + 3)(b + 2) biçiminde ortak çarpan parantezine alınır.'),
  ('(2025² − 2024²) / 4049 işleminin sonucu nedir?', '1', ['2', '4049', '1/2'], 'Pay (2025 − 2024)(2025 + 2024) = 1 · 4049\'dur; 4049\'a bölününce 1 kalır.'),
  ('a = 1,25 ve b = 0,75 için a² − 2ab + b² ifadesinin değerini en kısa yoldan bulunuz.', '0,25', ['4', '0,5', '0,025'], 'İfade (a − b)²\'dir: (1,25 − 0,75)² = 0,5² = 0,25.'),
  ('(x + 1)/3 − (x − 1)/4 = 2 denkleminde paydalar eşitlendikten sonra bulunan x kaçtır?', '17', ['7', '24', '−17'], '12 ile genişletilir: 4(x + 1) − 3(x − 1) = 24 ⇒ x + 7 = 24 ⇒ x = 17.'),
  ('0,2x + 1,5 = 0,5x − 0,3 denkleminin çözümü hangisidir?', '6', ['4', '−6', '0,6'], '1,5 + 0,3 = 0,5x − 0,2x ⇒ 1,8 = 0,3x ⇒ x = 6\'dır.'),
  ('(m − 1)x² + 4x − m = 0 denklemi birinci dereceden bir denklem olduğuna göre çözümü olan x kaçtır?', '1/4', ['4', '1', '−1/4'], 'Birinci dereceden olması için x²\'nin katsayısı 0 olmalıdır: m = 1. Denklem 4x − 1 = 0 ⇒ x = 1/4.'),
  ('|x| yerine k yazılarak çözülen 3|x| − 7 = 2|x| + 1 denkleminin kökleri çarpımı kaçtır?', '−64', ['64', '8', '0'], '|x| = 8 bulunur; x = 8 ya da x = −8, çarpımları −64\'tür.'),
  ('x + y = 8, y + z = 11 ve x + z = 9 eşitlikleri veriliyor. x + y + z toplamı kaçtır?', '14', ['28', '9', '19'], 'Üç denklem toplanırsa 2(x + y + z) = 28 ⇒ x + y + z = 14\'tür.'),
  ('1/x + 1/y = 5 ve 1/x − 1/y = 1 sisteminde x değeri kaçtır?', '1/3', ['3', '1/2', '2'], 'Denklemler toplanınca 2/x = 6 ⇒ 1/x = 3 ⇒ x = 1/3\'tür.'),
  ('Bir kantinde 2 tost ile 1 ayranın fiyatı 110 TL, 1 tost ile 2 ayranın fiyatı 85 TL\'dir. 1 tost ile 1 ayran birlikte kaç TL\'dir?', '65', ['55', '70', '195'], 'Denklemler toplanınca 3 tost + 3 ayran = 195 TL olur; 1 tost + 1 ayran = 65 TL\'dir.'),
  ('2ˣ · 3ʸ = 72 ve x, y doğal sayılar olduğuna göre x − y farkı kaçtır?', '1', ['2', '−1', '5'], '72 = 2³ · 3² olduğundan x = 3, y = 2\'dir; asal çarpanlara ayrılış tek olduğu için başka çözüm yoktur. x − y = 1.'),
  ('Paydalar 6 ile genişletilerek x/3 − 1 ≤ x/2 eşitsizliği çözülürse x için hangi koşul bulunur?', 'x ≥ −6', ['x ≤ −6', 'x ≥ 6', 'x ≥ −6/5'], '6 ile çarpılırsa 2x − 6 ≤ 3x ⇒ −6 ≤ x olur.'),
  ('(−1, 4] ve [2, 7) aralıklarının kesişimi hangisidir?', '[2, 4]', ['(−1, 7)', '[2, 7)', '(2, 4)'], 'Her iki aralıkta bulunan sayılar 2 ile 4 arasındakilerdir; 2 ikinci aralıkta, 4 birinci aralıkta dahildir: [2, 4].'),
  ('Üç parçalı 3x − 2 < 2x + 1 < 4x + 7 zincirinde iki eşitsizlik ayrı ayrı çözülüp ortak kısım alınırsa bu kısımda kaç tam sayı bulunur?', '5', ['3', '6', '4'], 'Sol taraftan x < 3, sağ taraftan −6 < 2x ⇒ x > −3. Tam sayılar −2, −1, 0, 1, 2: 5 tane.'),
  ('−3 < a < 2 aralığındaki a tam sayısı için a² ifadesinin alabileceği en büyük değer kaçtır?', '4', ['9', '1', '0'], 'a tam sayısı −2, −1, 0, 1 olabilir; a² en çok (−2)² = 4 olur. −3 aralıkta yer almaz.'),
  ('x ve y pozitif tam sayılar ve x + y = 10 olduğuna göre x · y çarpımının en büyük değeri kaçtır?', '25', ['24', '21', '100'], 'Toplamı sabit iki sayının çarpımı sayılar birbirine en yakınken en büyüktür: 5 · 5 = 25.'),
  ('x ve y pozitif tam sayılar ve x · y = 36 olduğuna göre x + y toplamının en küçük değeri hangisidir?', '12', ['13', '15', '37'], 'Çarpımı sabit iki sayının toplamı sayılar birbirine en yakınken en küçüktür: 6 + 6 = 12.'),
  ('x < 0 < y ve |x| < |y| olduğuna göre x + y toplamı için hangisi kesinlikle doğrudur?', 'x + y > 0', ['x + y < 0', 'x + y = 0', 'x + y < x − y'], 'Pozitif y\'nin mutlak değeri daha büyük olduğundan toplamın işareti y\'nin işaretidir; x + y > 0.'),
  ('x tam sayısı için −1 < 2x − 3 ≤ 9 olduğuna göre x\'in alabileceği değerlerin en büyüğü ile en küçüğünün toplamı kaçtır?', '8', ['7', '9', '6'], '2 < 2x ≤ 12 ⇒ 1 < x ≤ 6. Tam sayı değerleri 2\'den 6\'ya kadardır; en küçük 2, en büyük 6, toplam 8.'),
  ('a < b < c < d ardışık çift sayılardır ve a + d = 30\'dur. c − a farkı ve b\'nin değeri sırasıyla hangisidir?', '4 ve 14', ['2 ve 12', '4 ve 12', '12 ve 14'], 'Sayılar a, a + 2, a + 4, a + 6 ise 2a + 6 = 30 ⇒ a = 12. b = 14 ve c − a = 4\'tür.'),
  ('Aşağıdaki durumlardan hangisinde iki çokluk ters orantılıdır?', 'Sabit bir yolu gitmek için hız ile süre', ['Kalem sayısı ile ödenen toplam tutar', 'Bir karenin kenarı ile çevresi', 'Çalışılan saat ile saatlik ücretle kazanılan para'], 'Yol sabitken hız · süre = yol olduğundan hız artınca süre aynı oranda azalır. Diğerlerinde oranlar sabittir, yani doğru orantı vardır.'),
  ('a/b = 4/7 olduğuna göre (2a + b)/(a + b) oranı kaçtır?', '15/11', ['8/7', '11/15', '4/11'], 'a = 4k, b = 7k: (8k + 7k)/(4k + 7k) = 15/11.'),
  ('a, b, c sayıları sırasıyla 3, 4 ve 6 ile ters orantılıdır. a + b + c = 27 olduğuna göre a kaçtır?', '12', ['9', '6', '4'], 'a = k/3, b = k/4, c = k/6; toplam k(4 + 3 + 2)/12 = 9k/12 = 27 ⇒ k = 36. a = 12.'),
  ('a + b = 2(a − b) eşitliği veriliyor. a/b oranı kaçtır?', '3', ['1/3', '2', '3/2'], 'a + b = 2a − 2b ⇒ 3b = a ⇒ a/b = 3\'tür.'),
  ('4 ile 9 sayılarının orta orantılısı, yani 4/b = b/9 eşitliğini sağlayan pozitif b sayısı kaçtır?', '6', ['6,5', '13', '36'], 'İçler dışlar çarpımı b² = 36 verir; pozitif çözüm b = 6\'dır.'),
  ('Bir sayının karesinden kendisinin 4 katı çıkarıldığında 21 elde ediliyor. Bu koşulu sağlayan pozitif sayı nedir?', '7', ['3', '−3', '21/4'], 'x² − 4x − 21 = 0 ⇒ (x − 7)(x + 3) = 0; pozitif çözüm 7\'dir.'),
  ('Bir sayının 7 katı ile 3 katı arasındaki fark, sayının 20 fazlasına eşittir. Bu sayı kaçtır?', '20/3', ['5', '20/11', '4'], '7x − 3x = x + 20 ⇒ 3x = 20 ⇒ x = 20/3.'),
  ('Bir sayı 4\'e bölünüp 3 eklendiğinde, aynı sayının 6\'ya bölünüp 5 eklenmesiyle aynı sonuç bulunuyor. Sayı kaçtır?', '24', ['12', '18', '8'], 'x/4 + 3 = x/6 + 5 ⇒ x/4 − x/6 = 2 ⇒ x/12 = 2 ⇒ x = 24.'),
  ('Bir sayının 5 eksiği ile 5 fazlasının çarpımı 96\'dır. Bu sayının pozitif değeri kaçtır?', '11', ['9', '96', '√96'], '(x − 5)(x + 5) = x² − 25 = 96 ⇒ x² = 121 ⇒ x = 11.'),
  ('İki pozitif tam sayının toplamı 25\'tir. Büyük sayı küçük sayıya bölündüğünde bölüm 3, kalan 1 oluyor. Büyük sayı kaçtır?', '19', ['18', '6', '20'], 'Küçük sayı x ise büyük sayı 3x + 1\'dir: 4x + 1 = 25 ⇒ x = 6 ve büyük sayı 19\'dur. Kalan 1, bölen 6\'dan küçük olduğundan uygundur.'),
  ('Bir kitabın önce 1/3\'ü, sonra kalanın 1/4\'ü okunuyor. Okunmayan kısım kitabın kaçta kaçıdır?', '1/2', ['5/12', '7/12', '2/3'], 'İlk okumadan sonra 2/3 kalır; bunun 1/4\'ü 1/6 okunur. Toplam okunan 1/3 + 1/6 = 1/2, kalan 1/2\'dir.'),
  ('Bir öğrenci harçlığının 2/5\'ini kitaba, 1/3\'ünü yemeğe harcadığında elinde 120 TL kalıyor. Harçlığı kaç TL\'dir?', '450', ['300', '360', '1800'], 'Harcanan 2/5 + 1/3 = 11/15, kalan 4/15\'tir. 4/15 · x = 120 ⇒ x = 450.'),
  ('Bir sınıftaki öğrencilerin 3/8\'i gözlüklüdür. Gözlüklü olmayan öğrenci sayısı gözlüklülerden 6 fazla olduğuna göre sınıf mevcudu kaçtır?', '24', ['16', '32', '48'], 'Gözlüksüzler 5/8, fark 2/8 = 1/4\'tür. 1/4 · x = 6 ⇒ x = 24.'),
  ('Bir ip önce yarısından, sonra kalan parçanın üçte birinden kesiliyor. En sonda elde kalan parça 8 m olduğuna göre ipin ilk uzunluğu kaç metredir?', '24', ['16', '18', '12'], 'Yarısı kesilince 1/2, kalanın 1/3\'ü kesilince 1/2 · 2/3 = 1/3 kalır. 1/3 · x = 8 ⇒ x = 24 m.'),
  ('Bir çiftçi tarlasının 3/5\'ine buğday, kalanın 1/2\'sine arpa ekiyor ve geriye ekilmemiş 12 dönüm kalıyor. Tarla kaç dönümdür?', '60', ['30', '40', '24'], 'Buğdaydan sonra 2/5 kalır; bunun yarısı 1/5 arpa, kalan 1/5 ekilmemiştir. 1/5 · x = 12 ⇒ x = 60 dönüm.'),
  ('7 sayısının kuvvetlerinin birler basamakları 7, 9, 3, 1 biçiminde dörtlü bir döngü izler. Buna göre 7⁵⁰ sayısının birler basamağı kaçtır?', '9', ['7', '3', '1'], '50 = 4 · 12 + 2 olduğundan 7⁵⁰\'nin birler basamağı döngünün 2. elemanı olan 9\'dur.'),
  ('2¹⁰⁰ sayısının birler basamağındaki rakamı belirlemek için 2\'nin kuvvetlerindeki 2, 4, 8, 6 döngüsü kullanılır. Bu rakam nedir?', '6', ['2', '4', '8'], '100, 4\'ün tam katı olduğundan birler basamağı döngünün son elemanı olan 6\'dır.'),
  ('3²⁰ + 4²⁰ toplamının birler basamağı kaçtır?', '7', ['1', '3', '5'], '3\'ün kuvvetlerinde döngü 3, 9, 7, 1\'dir ve 20, 4\'ün katı ⇒ 1. 4\'ün çift kuvvetleri 6 ile biter. 1 + 6 = 7.'),
  ('Saat 12 düzeninde çalışan bir saatin akrebi şu an 9\'u gösteriyor. 100 saat sonra akrep hangi sayıyı gösterir?', '1', ['9', '4', '10'], '100 = 12 · 8 + 4 olduğundan 100 saat sonra akrep 4 saat ileri gitmiş gibi olur: 9 + 4 = 13 ⇒ 1.'),
  ('13 · 17 · 19 çarpımının 5\'e bölümünden kalan, çarpanların kalanları çarpılarak bulunur. Kalan kaçtır?', '4', ['3', '1', '2'], 'Kalanlar 3, 2 ve 4\'tür: 3 · 2 · 4 = 24 ve 24\'ün 5\'e bölümünden kalan 4\'tür.'),
  ('Onluk tabandaki 25 sayısının üçlük tabandaki yazılışı hangisidir?', '(221)₃', ['(212)₃', '(122)₃', '(1021)₃'], '25 = 2 · 9 + 2 · 3 + 1 olduğundan (221)₃\'tür.'),
  ('(101)ₐ = 26 olduğuna göre a tabanı kaçtır?', '5', ['4', '25', '6'], '(101)ₐ = a² + 1 = 26 ⇒ a² = 25 ⇒ a = 5.'),
  ('İkilik tabanda yazılan (111111)₂ sayısının onluk karşılığı hangisidir?', '63', ['64', '111111', '32'], 'Altı tane 1\'den oluşan ikilik sayı 2⁶ − 1 = 63\'tür.'),
  ('(12)₃ + (21)₃ toplamının 3 tabanındaki sonucu hangisidir?', '(110)₃', ['(33)₃', '(100)₃', '(1010)₃'], '(12)₃ = 5 ve (21)₃ = 7, toplam 12\'dir; 12 = 1 · 9 + 1 · 3 + 0 = (110)₃.'),
  ('Onluk tabandaki 100 sayısı ikilik tabanda kaç basamaklı yazılır?', '7', ['6', '8', '3'], '2⁶ = 64 ≤ 100 < 128 = 2⁷ olduğundan 100 ikilik tabanda 7 basamaklıdır: (1100100)₂.'),
  ('100 ile 300 arasında (iki sayı da dahil) 7\'ye tam bölünen kaç tam sayı vardır?', '28', ['29', '27', '200'], 'İlk kat 105, son kat 294\'tür: (294 − 105)/7 + 1 = 27 + 1 = 28.'),
  ('1\'den 100\'e kadar olan doğal sayılardan kaç tanesi 3\'e ya da 5\'e bölünür?', '47', ['41', '33', '20'], '3\'ün katları 33, 5\'in katları 20, 15\'in katları 6 tanedir: 33 + 20 − 6 = 47.'),
  ('Sayı doğrusunda 3 noktasına uzaklığı 5 birimden az olan kaç tam sayı vardır?', '9', ['10', '11', '8'], '|x − 3| < 5 ⇒ −2 < x < 8; tam sayılar −1\'den 7\'ye kadar 9 tanedir.'),
  ('50 ile 150 arasında olup hem 6\'ya hem 8\'e tam bölünen kaç sayı vardır?', '4', ['2', '3', '6'], 'Hem 6\'ya hem 8\'e bölünen sayılar EKOK(6, 8) = 24\'ün katlarıdır. Aralıktaki katlar 72, 96, 120 ve 144 olmak üzere 4 tanedir; 48\'in katı aranırsa yanlışlıkla 2 bulunur.'),
  ('A = {1, 2, 3, 4, 5} kümesinin, içinde 1\'in bulunduğu ama 5\'in bulunmadığı kaç alt kümesi vardır?', '8', ['16', '12', '32'], '1 kesin alınır, 5 kesin alınmaz; kalan 2, 3, 4 elemanları serbesttir: 2³ = 8.'),
  ('A ⊂ B ve s(B) = 10 iken s(A ∪ B) kaçtır?', '10', ['Belirlenemez', '20', 's(A) + 10'], 'A, B\'nin alt kümesi olduğundan A ∪ B = B\'dir; eleman sayısı 10\'dur.'),
  ('De Morgan kuralına göre (A ∪ B)\' kümesi aşağıdakilerden hangisine eşittir?', 'A\' ∩ B\'', ['A\' ∪ B\'', 'A ∩ B', 'A ∪ B\''], 'Birleşimin tümleyeni tümleyenlerin kesişimidir: (A ∪ B)\' = A\' ∩ B\'.'),
  ('Yalnız A\'da bulunan 7, yalnız B\'de bulunan 5 eleman vardır ve birleşim kümesi 20 elemanlıdır. Kesişim kümesinin eleman sayısı nedir?', '8', ['12', '13', '3'], 'Birleşim, yalnız A, yalnız B ve ortak kısımdan oluşur: 20 = 7 + 5 + s(A ∩ B) ⇒ 8.'),
  ('Alt küme sayısı, 3 elemanlı bir kümenin alt küme sayısından 56 fazla olan küme kaç elemanlıdır?', '6', ['5', '7', '64'], '3 elemanlı kümenin 8 alt kümesi vardır. 2ⁿ = 64 ⇒ n = 6.'),
  ('"Her öğrenci sınava girdi." önermesinin değili aşağıdakilerden hangisidir?', 'En az bir öğrenci sınava girmedi.', ['Okuldaki öğrenciler sınava girmemiştir.', 'Her öğrenci sınava girmedi.', 'Bazı öğrenciler sınava girdi.'], '"Her" niceleyicisinin değili "en az bir ... değil" biçimindedir: ∀x p(x) önermesinin değili ∃x p(x)\' olur.'),
  ('p ∨ p\' bileşik önermesinin doğruluk değeri için ne söylenebilir?', 'Her zaman doğrudur', ['Her zaman yanlıştır', 'p doğruysa doğrudur', 'p yanlışsa yanlıştır'], 'Bir önerme ile değilinden biri mutlaka doğrudur; "veya" bağlacı en az biri doğru olduğunda doğrudur. Bu bir totolojidir.'),
  ('(p ∧ q)\' önermesi De Morgan kuralına göre hangisine denktir?', 'p\' ∨ q\'', ['p\' ∧ q\'', 'p ∨ q', 'p\' ∨ q'], '"ve" bağlacının değili, değillerin "veya" ile bağlanmasıdır: (p ∧ q)\' ≡ p\' ∨ q\'.'),
  ('p: "3 > 5", q: "2 + 2 = 4" önermeleri için p ⇒ q koşullu önermesinin doğruluk değeri nedir?', 'Doğru', ['Yanlış', 'Belirlenemez', 'Önerme değildir'], 'p yanlıştır. Hipotezi yanlış olan koşullu önerme hüküm ne olursa olsun doğrudur.'),
  ('"Bazı tam sayılar negatiftir." önermesinin niceleyiciyle yazılışı ve doğruluk değeri hangisidir?', '∃x ∈ Z, x < 0; doğru', ['∀x ∈ Z, x < 0; yanlış', '∀x ∈ Z, x < 0; doğru', '∃x ∈ Z, x < 0; yanlış'], '"Bazı" ifadesi varlık niceleyicisi ∃ ile gösterilir. −1 gibi negatif tam sayılar bulunduğundan önerme doğrudur.'),
  ('Bir öğrenci 24 : 4 · 2 işlemini 24 : 8 = 3 olarak hesaplamıştır. Doğru sonuç ve öğrencinin hatası hangisidir?', '12; soldan sağa işlem yapmamıştır', ['3; hata yoktur', '12; bölmeyi çarpmadan önce yapmıştır', '48; çarpmayı unutmuştur'], 'Çarpma ile bölme eşit önceliklidir ve soldan sağa yapılır: 24 : 4 = 6, 6 · 2 = 12.'),
  ('−2² · 3 + (−2)³ işleminin değeri kaçtır?', '−20', ['4', '20', '−4'], '−2² = −4 olduğundan −4 · 3 = −12; (−2)³ = −8. Toplam −12 − 8 = −20.'),
  ('3 + 5 · 2 − 4 işleminin sonucunun 12 olması için hangi iki sayının arasına parantez konmalıdır?', '3 ile 5', ['5 ile 2', '2 ile 4', '3 ile 2'], '(3 + 5) · 2 − 4 = 16 − 4 = 12 olur. Parantez olmadan sonuç 3 + 10 − 4 = 9\'dur.'),
  ('Bölmeler toplama ve çıkarmadan önce yapılırsa 1 − 1 : 2 + 1 : 4 − 1 : 8 ifadesi hangi kesre eşit olur?', '5/8', ['1/8', '0', '15/8'], 'Bölmeler önce: 1 − 1/2 + 1/4 − 1/8 = (8 − 4 + 2 − 1)/8 = 5/8.'),
  ('Bir öğrenci 49 · 21 çarpımını tahmin etmek için sayıları en yakın onluğa yuvarlıyor. Tahmini sonuç ile gerçek sonuç arasındaki fark kaçtır?', '29', ['1', '71', '19'], 'Tahmin 50 · 20 = 1000, gerçek sonuç 49 · 21 = 1029\'dur; fark 29\'dur.'),
  ('(8 · 10⁻³) / (2 · 10⁻⁷) bölümünün değeri nedir?', '4 · 10⁴', ['4 · 10⁻¹⁰', '4 · 10⁻⁴', '16 · 10⁴'], 'Katsayılar 8/2 = 4, üsler −3 − (−7) = 4 ⇒ 4 · 10⁴.'),
  ('Bir sayının 12\'ye bölümünden kalan 7\'dir. Aynı sayının 4\'e bölümünden kalan kaçtır?', '3', ['7', '1', '0'], 'Sayı 12k + 7 biçimindedir; 12k, 4\'e bölünür ve 7\'nin 4\'e bölümünden kalan 3\'tür.'),
  ('Bir sayının 7\'ye bölümünden kalan 3 ise bu sayının küpünün 7\'ye bölümünden kalan kaçtır?', '6', ['3', '1', '27'], '3³ = 27 = 3 · 7 + 6 olduğundan kalan 6\'dır.'),
  ('Bir sayının 15\'e bölümünden kalan 11\'dir. Aynı sayının 5\'e bölümünden bölüm 8 olduğuna göre sayı kaçtır?', '41', ['43', '56', '26'], '15k + 11 biçimindeki sayılar 11, 26, 41, 56, ...\'dır. 5\'e bölümünden bölüm 8 olan sayı 40 ile 44 arasında olmalıdır: 41.'),
  ('Ardışık üç doğal sayının 3\'e bölümünden elde edilen kalanların toplamı her zaman kaçtır?', '3', ['0', '6', '2'], 'Ardışık üç sayının 3\'e bölümünden kalanlar sırası ne olursa olsun 0, 1 ve 2\'dir; toplamları 3\'tür.'),
  ('Birler basamağı 6 olan bir x doğal sayısı için x² − x farkının birler basamağı hangi rakamdır?', '0', ['2', '6', '4'], 'Kalan 6² − 6 = 30 ifadesinin kalanıdır; 30, 10\'a tam bölünür ve kalan 0\'dır.'),
  ('Bir sayı 4, 5 ve 6\'ya bölündüğünde her seferinde 3 kalanını veriyor. Bu koşulu sağlayan üç basamaklı en küçük sayı kaçtır?', '123', ['63', '183', '120'], 'Sayı EKOK(4, 5, 6) = 60\'ın katından 3 fazladır: 60k + 3. Üç basamaklı en küçük değer 123\'tür.'),
  ('Değeri 3/4 olan bir kesrin pay ve paydası toplandığında 56 bulunuyor. Bu kesrin alt kısmındaki sayı nedir?', '32', ['24', '28', '22'], 'Kesir 3k/4k biçimindedir: 7k = 56 ⇒ k = 8; payda 4k = 32\'dir.'),
  ('Bir öğrenci 16/64 kesrinde paydaki ve paydadaki 6 rakamlarını silerek 1/4 sonucunu bulmuştur. Bu yöntem ve sonuç için hangisi doğrudur?', 'Sonuç doğru, yöntem yanlıştır', ['Yöntem de sonuç da tamamen doğrudur', 'Yöntem doğru, sonuç yanlıştır', 'Yöntem de sonuç da yanlıştır'], '16/64 gerçekten 1/4\'e eşittir, ancak rakam silmek geçerli bir sadeleştirme değildir; örneğin 12/24\'te 2\'ler silinirse 1/4 bulunur, oysa kesir 1/2\'dir.'),
  ('(x² − 4)/(2x − 4) kesri x ≠ 2 için sadeleştirildiğinde hangi ifade elde edilir?', '(x + 2)/2', ['x + 2', '(x − 2)/2', '(x + 2)/(x − 2)'], 'Pay (x − 2)(x + 2), payda 2(x − 2)\'dir; ortak çarpan sadeleşince (x + 2)/2 kalır.'),
  ('2/7 kesrine denk olan kesirler arasında payı iki basamaklı en küçük sayı olan kesrin paydası kaçtır?', '35', ['70', '42', '49'], 'Denk kesirler 2k/7k biçimindedir. Pay iki basamaklı en küçük olmalı: 2k ≥ 10 ⇒ k = 5; payda 35\'tir.'),
  ('7/16 kesrinin ondalık gösterimi aşağıdakilerden hangisidir?', '0,4375', ['0,4365', '0,4', '0,04375'], '16 = 2⁴ olduğundan açılım sonludur: 7/16 = 7 · 625/10 000 = 0,4375.'),
  ('2,05 sayısının tam sayılı kesir biçimi hangisidir?', '2 1/20', ['2 5/10', '2 1/5', '2 5/1000'], '0,05 = 5/100 = 1/20 olduğundan 2,05 = 2 1/20\'dir.'),
  ('Aşağıdaki sıralamalardan hangisi doğrudur?', '0,3 < 1/3 < 0,34', ['1/3 < 0,3 < 0,34', '0,34 < 1/3 < 0,3', '0,3 < 0,34 < 1/3'], '1/3 = 0,333...\'tür; 0,3 < 0,333... < 0,34 olur.'),
  ('1/8, 0,13, 3/25 ve 0,124 sayıları küçükten büyüğe sıralandığında ikinci sırada hangisi yer alır?', '0,124', ['3/25', '1/8', '0,13'], '1/8 = 0,125 ve 3/25 = 0,12\'dir. Sıralama 0,12 < 0,124 < 0,125 < 0,13 olduğundan ikinci sayı 0,124\'tür.'),
  ('Bir sayının 0,25\'i 7 ise sayının 0,8\'i kaçtır?', '22,4', ['16,8', '0,224', '2,24'], 'Sayı 7 / 0,25 = 28\'dir; 28 · 0,8 = 22,4.'),
  ('Paydası 40 olan bir kesir ondalık olarak 0,175\'tir. Kesrin payı kaçtır?', '7', ['17,5', '1,75', '70'], '0,175 · 40 = 7\'dir; kesir 7/40\'tır.'),
  ('Rakamları çarpımı 0 olmayan ve rakamları toplamı 10 olan iki basamaklı sayıların en büyüğü ile en küçüğünün farkı kaçtır?', '72', ['81', '63', '90'], 'Rakamlar sıfırdan farklı olmalıdır. En büyük 91, en küçük 19\'dur; fark 72.'),
  ('Beş öğrencinin not ortalaması 70\'tir. Notlar 0 ile 100 arasında tam sayı olduğuna göre en düşük not en az kaç olabilir?', '0', ['30', '50', '20'], 'Toplam 350\'dir. Diğer dört öğrenci 100 alırsa 400 > 350 olur; bu nedenle en düşük not 0 olabilir (örneğin 100, 100, 100, 50, 0).'),
  ('Bir kutuda 12 kırmızı, 8 mavi top vardır. Gözü kapalı en az kaç top çekilirse çekilenler arasında mutlaka her iki renkten de top bulunur?', '13', ['9', '3', '21'], 'En kötü durumda önce 12 kırmızı çekilir; 13. top mutlaka mavi olur.'),
  ('x tam sayısı −3 ile 2 arasında, y tam sayısı 1 ile 4 arasında değer alıyor (uçlar dahil). x\'in karesinden y çıkarılırsa ulaşılabilecek en yüksek sonuç nedir?', '8', ['11', '9', '13'], 'x² en çok (−3)² = 9, y en az 1 olmalıdır: 9 − 1 = 8.'),
  ('İki pozitif sayının toplamı 13, kareleri toplamı 89\'dur. Bu sayıların çarpımı kaçtır?', '40', ['76', '60', '169'], '(a + b)² = a² + b² + 2ab ⇒ 169 = 89 + 2ab ⇒ ab = 40.'),
  ('Toplamları 40 olan iki sayıdan birinin 1/3\'ü diğerinin 1/5\'ine eşittir. Küçük sayı kaçtır?', '15', ['5', '8', '13,5'], 'a/3 = b/5 ⇒ a = 3k, b = 5k; 8k = 40 ⇒ k = 5. Küçük sayı 15\'tir.'),
  ('İki sayının toplamı 20, çarpımı 91\'dir. Bu sayıların farkının mutlak değeri kaçtır?', '6', ['7', '13', '36'], '(a − b)² = (a + b)² − 4ab = 400 − 364 = 36 ⇒ |a − b| = 6. Sayılar 13 ve 7\'dir.'),
  ('İki sayıdan büyüğü 7 azaltılır, küçüğü 7 artırılırsa sayılar eşit oluyor. Sayıların toplamı 50 ise büyük sayı kaçtır?', '32', ['25', '18', '21'], 'Büyük ile küçük arasındaki fark 14\'tür. Toplam 50 ise büyük sayı (50 + 14)/2 = 32\'dir.'),
  ('İki sayının çarpımı 60 ve büyük sayı küçük sayının 15 katıdır. Bu sayıların toplamı kaçtır?', '32', ['30', '64', '17'], 'Küçük x ise 15x² = 60 ⇒ x = 2. Sayılar 2 ve 30, toplamları 32\'dir. (Pozitif sayılar alınmıştır.)'),
  ('Bir ağaçtaki her dala birer kuş konarsa bir kuş açıkta kalıyor; her dala ikişer kuş konarsa bir dal boş kalıyor. Kaç kuş vardır?', '4', ['3', '5', '6'], 'Dal sayısı d ise kuş d + 1 = 2(d − 1) ⇒ d = 3. Kuş sayısı 4\'tür.'),
  ('Bir şişe ile mantarı birlikte 110 TL\'dir. Şişe, mantardan 100 TL pahalı olduğuna göre mantar kaç TL\'dir?', '5', ['10', '55', '7,5'], 'Mantar m ise m + (m + 100) = 110 ⇒ 2m = 10 ⇒ m = 5 TL. Sezgisel olarak verilen 10 TL yanıtı yanlıştır.'),
  ('Bir salonda sıralara ikişer kişi oturulursa 6 kişi ayakta kalıyor, üçer kişi oturulursa 2 sıra tamamen boş kalıyor. Salonda kaç kişi vardır?', '30', ['12', '24', '36'], 'Sıra sayısı s ise 2s + 6 = 3(s − 2) ⇒ s = 12; kişi sayısı 2 · 12 + 6 = 30.'),
  ('Bir öğrenci bir sayının 3 katına 5 ekleyeceğine yanlışlıkla 5 katına 3 eklemiş ve doğru sonuçtan 10 fazla bulmuştur. Sayı kaçtır?', '6', ['4', '5', '3'], '(5x + 3) − (3x + 5) = 10 ⇒ 2x − 2 = 10 ⇒ x = 6.'),
  ('Bir sayının 2 fazlasının karesi, aynı sayının 2 eksiğinin karesinden 48 fazladır. Sayı kaçtır?', '6', ['12', '8', '4'], '(x + 2)² − (x − 2)² = 8x = 48 ⇒ x = 6.'),
  ('Bir otoparktaki arabaların 2/3\'ü çıktıktan sonra 14 araba daha geliyor ve otopark ilk durumundan 6 araba eksik kalıyor. Başlangıçta kaç araba vardı?', '30', ['20', '21', '18'], 'x − 2x/3 + 14 = x − 6 ⇒ 2x/3 = 20 ⇒ x = 30.'),
  ('Birler basamağındaki rakamı onlar basamağındaki rakamın 2 katı olan iki basamaklı bir sayının rakamlarının yerleri değiştirildiğinde sayı 36 artıyor. Bu sayı kaçtır?', '48', ['24', '36', '12'], 'Sayı 10a + 2a = 12a, ters çevrilmiş hâli 20a + a = 21a\'dır. 21a − 12a = 9a = 36 ⇒ a = 4 ve sayı 48\'dir.'),
  ('Bir otobüs durağından her 12 dakikada bir otobüs kalkıyor. İlk otobüs 06.40\'ta kalktığına göre saat 09.00\'a kadar (09.00 dahil) kaç otobüs kalkar?', '12', ['11', '13', '14'], '06.40\'tan 09.00\'a 140 dakika vardır; 140/12 = 11,6 olduğundan ilk otobüsle birlikte 11 + 1 = 12 sefer yapılır.'),
  ('Toplamları −5, çarpımları −24 olan iki tam sayının büyüğü kaçtır?', '3', ['−2', '−3', '−8'], 'Çarpım negatif olduğundan işaretler farklıdır; toplamı −5 olan çift −8 ve 3\'tür. Büyük olan 3.'),
  ('Bir tam sayı ile toplama işlemine göre tersinin toplamı ve çarpımı sırasıyla hangisidir? (Sayı a ≠ 0 olsun.)', '0 ve −a²', ['0 ve a²', '2a ve −a²', '0 ve 1'], 'a + (−a) = 0; a · (−a) = −a²\'dir.'),
  ('a = −2, b = 3 ve c = −4 için a · b − b · c + a · c ifadesinin değeri kaçtır?', '14', ['−14', '−10', '10'], 'a · b = −6; b · c = −12 ⇒ −b · c = 12; a · c = 8. Toplam −6 + 12 + 8 = 14.'),
  ('−15 ile 9 arasındaki tam sayıların (uçlar hariç) toplamı kaçtır?', '−69', ['−75', '−6', '−84'], 'Aradaki sayılar −14\'ten 8\'e kadardır. −8 ile 8 arasındakiler birbirini götürür; geriye −14 − 13 − 12 − 11 − 10 − 9 = −69 kalır.'),
  ('Karekökü 3√2 olan pozitif x sayısını bulmak için eşitliğin iki tarafının karesi alınıyor. x nedir?', '18', ['6', '36', '3√2'], 'Her iki tarafın karesi alınır: x = 2 · 9 = 18.'),
  ('Kesirli üs mantığıyla (√3)⁶ ve (∛2)⁶ değerleri ayrı ayrı bulunup toplanırsa sonuç ne olur?', '31', ['27', '13', '9√3'], '(√3)⁶ = 3³ = 27, (∛2)⁶ = 2² = 4; toplam 31.'),
  ('Bir kenarı √8 cm olan bir küpün hacmi kaç cm³\'tür?', '16√2', ['8√2', '24', '16√8'], 'Hacim (√8)³ = 8√8 = 8 · 2√2 = 16√2 cm³\'tür.'),
  ('Kök içinde üç eş terim bulunan √(3⁴ + 3⁴ + 3⁴) sayısının en sade köklü biçimi nedir?', '9√3', ['27', '3√12', '81'], '3 · 3⁴ = 3⁵ olduğundan √(3⁵) = 3² · √3 = 9√3.'),
  ('Ondalık sayı ile 10\'un kuvvetinin çarpımından oluşan √(0,16 · 10⁶) karekökü hangi doğal sayıdır?', '400', ['40', '4000', '1,6 · 10³'], '0,16 · 10⁶ = 160 000 = 16 · 10⁴; karekökü 4 · 10² = 400.'),
  ('Kendisi hariç pozitif bölenlerinin toplamı kendisine eşit olan sayılara mükemmel sayı denir. Aşağıdakilerden hangisi mükemmel sayıdır?', '28', ['24', '12', '18'], '28\'in kendisi hariç bölenleri 1, 2, 4, 7, 14\'tür ve toplamları 28\'dir. 12 için toplam 16, 18 için 21, 24 için 36\'dır.'),
  ('a sayısı 12\'nin, b sayısı 18\'in pozitif bir katıdır. a + b toplamı aşağıdakilerden hangisinin kesinlikle katıdır?', '6', ['12', '18', '36'], '12 ile 18\'in ortak böleni olan her sayı toplamı da böler; en büyüğü EBOB = 6\'dır. 12 + 18 = 30 örneği 12, 18 ve 36\'nın garanti olmadığını gösterir.'),
  ('1 ile 50 arasındaki tam kare sayıların (1 ve 50 dahil) toplamı kaçtır?', '140', ['91', '100', '49'], 'Tam kareler 1, 4, 9, 16, 25, 36, 49\'dur; toplamları 140\'tır.'),
  ('Bir sayı 2\'ye, 3\'e ve 4\'e bölündüğünde hep 1 kalanını veriyor ve 5\'e tam bölünüyor. Bu koşulu sağlayan en küçük doğal sayı kaçtır?', '25', ['37', '49', '61'], 'Sayı 12k + 1 biçimindedir: 1, 13, 25, 37, ...; 5\'e bölünen en küçüğü 25\'tir.'),
  ('Ardışık üç pozitif tam sayının kareleri toplamı 110\'dur. Bu üç sayının toplamı kaçtır?', '18', ['15', '21', '−18'], 'Ortadaki sayı n ise 3n² + 2 = 110 ⇒ n² = 36 ⇒ n = 6. Sayılar 5, 6, 7 ve toplamları 18\'dir.'),
  ('3\'e ve 5\'e tam bölünen bir doğal sayının 3\'e bölümünden elde edilen bölüm, 5\'e bölümünden elde edilen bölümden 4 fazladır. Sayı kaçtır?', '30', ['15', '20', '4,5'], 'n/3 − n/5 = 4 ⇒ 2n/15 = 4 ⇒ n = 30.'),
  ('Pozitif bir sayının yarısı ile üçte birinin çarpımı 54\'tür. Bu sayı kaçtır?', '18', ['9', '27', '−18'], '(x/2)(x/3) = x²/6 = 54 ⇒ x² = 324 ⇒ x = 18.'),
  ('3ˣ = 5 bilgisi kullanılarak 3²ˣ⁻¹ sayısı hesaplanırsa sonuç hangisidir?', '25/3', ['9', '10/3', '25 · 3'], '3²ˣ⁻¹ = (3ˣ)² / 3 = 25/3.'),
  ('Bir A kümesinin 2 elemanlı alt kümelerinin sayısı 15\'tir. A kümesi kaç elemanlıdır?', '6', ['5', '15', '30'], 'n(n − 1)/2 = 15 ⇒ n(n − 1) = 30 ⇒ n = 6.'),
  ('p ⇒ q koşullu önermesinin doğru, q önermesinin yanlış olduğu biliniyor. p önermesi için ne söylenebilir?', 'Yanlıştır', ['Doğrudur', 'Belirlenemez', 'q\'ya göre değişir'], 'p doğru olsaydı p ⇒ q yanlış olurdu. Koşullu önerme doğru ve q yanlış olduğundan p yanlış olmalıdır.'),
  ('a + b = 3c ve a − b = c eşitlikleri veriliyor (c ≠ 0). a/b oranı kaçtır?', '2', ['3', '1/2', '3/2'], 'Eşitlikler toplanınca 2a = 4c ⇒ a = 2c; b = c bulunur. a/b = 2.'),
  ('Karesi kendisinden küçük olan gerçek sayılar hangi aralıkta bulunur?', '0 < x < 1', ['x > 1', 'x < 0', '−1 < x < 0'], 'x² < x ⇒ x(x − 1) < 0 eşitsizliği yalnız 0 < x < 1 aralığında sağlanır. Örneğin 0,5² = 0,25 < 0,5\'tir.'),
  ('Bir sayının 0,2\'si ile 0,02\'sinin toplamı 11\'dir. Bu sayı kaçtır?', '50', ['55', '500', '60'], '0,2x + 0,02x = 0,22x = 11 ⇒ x = 50.'),
  ('Ardışık dört tek sayının toplamı her zaman aşağıdaki sayılardan hangisine tam bölünür?', '8', ['16', '24', '12'], 'Sayılar 2n + 1, 2n + 3, 2n + 5, 2n + 7 ise toplam 8n + 16 = 8(n + 2)\'dir. 1 + 3 + 5 + 7 = 16, 3 + 5 + 7 + 9 = 24 örnekleri 16\'nın garanti olmadığını gösterir.'),
];
